CREATE TABLE public.staff_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, requested_role public.app_role NOT NULL CHECK(requested_role IN ('facilitator','admin')), reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 2000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,requested_role));
GRANT SELECT, INSERT ON public.staff_requests TO authenticated; GRANT ALL ON public.staff_requests TO service_role;
ALTER TABLE public.staff_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "request owner or admin reads" ON public.staff_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "request own pending access" ON public.staff_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reviewed_by IS NULL AND reviewed_at IS NULL);
CREATE FUNCTION public.review_staff_request(request_id uuid, approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.staff_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO r FROM public.staff_requests WHERE id=request_id AND status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request is not pending'; END IF; IF approve THEN INSERT INTO public.user_roles(user_id,role) VALUES(r.user_id,r.requested_role) ON CONFLICT DO NOTHING; END IF; UPDATE public.staff_requests SET status=CASE WHEN approve THEN 'approved' ELSE 'rejected' END, reviewed_by=auth.uid(),reviewed_at=now() WHERE id=request_id; END $$;
REVOKE ALL ON FUNCTION public.review_staff_request(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_staff_request(uuid,boolean) TO authenticated;
CREATE TABLE public.knowledge_articles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,vegetable_id uuid REFERENCES public.vegetables(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),created_by uuid DEFAULT auth.uid(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.knowledge_articles TO authenticated; GRANT SELECT ON public.knowledge_articles TO anon; GRANT ALL ON public.knowledge_articles TO service_role;
ALTER TABLE public.knowledge_articles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "published library reads" ON public.knowledge_articles FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY "staff manage library" ON public.knowledge_articles FOR ALL TO authenticated USING(public.has_role(auth.uid(),'facilitator') OR public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'facilitator') OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ai_service_state(service text PRIMARY KEY,paused boolean NOT NULL DEFAULT false,reason text,requires text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_service_state TO service_role; ALTER TABLE public.ai_service_state ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.courses,public.course_modules,public.lessons TO authenticated;
CREATE FUNCTION public.resume_learning_ai() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.ai_service_state SET paused=false,reason=NULL,requires=NULL,updated_at=now() WHERE service='learning' AND requires IS DISTINCT FROM 'provider_access'; END $$;
REVOKE ALL ON FUNCTION public.resume_learning_ai() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resume_learning_ai() TO authenticated;